import math

def solution(input_str):
    l, r = map(int, input_str.strip().split())

    # If l > r, return 0
    if l > r:
        return f"0\n"

    # Generate primes up to sqrt(r) using simple sieve
    sqrt_r = int(math.isqrt(r)) + 1
    small_primes = []
    is_prime_small = [True] * (sqrt_r + 1)
    is_prime_small[0] = is_prime_small[1] = False

    for i in range(2, sqrt_r + 1):
        if is_prime_small[i]:
            small_primes.append(i)
            for j in range(i * i, sqrt_r + 1, i):
                is_prime_small[j] = False

    # Segment [0, r-l] marking initially all as potentially prime
    offset = l
    n = r - l + 1
    is_prime = [True] * n

    # If l = 1, mark 1 as not prime
    if l == 1:
        is_prime[0] = False

    # For each prime p in small_primes, mark its multiples in [l, r]
    for p in small_primes:
        if p == 2 and l > 2:
            # Start from first multiple of 2 that is >= l and > 2
            start = (l + 1) // 2 * 2
            while start < l:
                start += 2
            start = max(start, p * p)
        else:
            start = p * p if p * p >= l else p * ((l + p - 1) // p)

        # Mark multiples in segmented array
        for j in range(start, r + 1, p):
            is_prime[j - offset] = False

    # Count primes that are either 2 or ≡ 1 (mod 4)
    count = 0
    for i in range(l, r + 1):
        if is_prime[i - l]:
            if i == 2 or i % 4 == 1:
                count += 1

    return f"{count}\n"


