import sys
from collections import deque

def build_adjacency(n, m, edges):
    adj = [[] for _ in range(n + 1)]
    for idx, (u, v, w) in enumerate(edges):
        adj[u].append((v, w, idx + 1))
        adj[v].append((u, w, idx + 1))
    return adj

def bfs_connected(adj, start, target, n):
    visited = [False] * (n + 1)
    queue = deque([start])
    visited[start] = True
    while queue:
        node = queue.popleft()
        if node == target:
            return True
        for neighbor, w, _ in adj[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
    return False

