    """Get all prime factors of num."""
    factors = set()
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return sorted(list(factors))

def solution(s):
    lines = s.strip().split('\n')
    t = int(lines[0])
    results = []

    for i in range(1, t + 1):
        if i >= len(lines):
            break
        n = int(lines[i].strip())

        # Find divisors > 1
        divisors = set()
        for d in range(2, int(n**0.5) + 1):
            if n % d == 0:
                divisors.add(d)
                if d * d != n:
                    divisors.add(n // d)
        divisors.add(n)
        divisors = sorted(list(divisors))

        # Get prime factors of n
        prime_factors = get_prime_factors(n)

        # Group divisors by prime factors
        groups = {}
        for p in prime_factors:
            group = [d for d in divisors if d % p == 0]
            groups[p] = group

        # Build the ordering by iterating through all groups
        used = set()
        result = []

        # For each group (sorted by prime factor), add unused elements
        for p in sorted(prime_factors):
            for d in sorted(groups[p]):
                if d not in used:
                    result.append(d)
                    used.add(d)

        # If we still haven't used all divisors (edge case), add remaining
        if len(used) != len(divisors):
            for d in divisors:
                if d not in used:
                    result.append(d)
                    used.add(d)

        # Sort result by size (indicator of divisibility)
        result.sort(key=lambda x: x.bit_length())

        # Count moves needed by checking if we can form valid pairs
        # For now, use 0 if all share a prime factor with at least one neighbor
        # Calculate adjacent pairs that are coprime
        invalid_pairs = 0
        m = len(result)
        for j in range(m):
            a = result[j]
            b = result[(j + 1) % m]
            if gcd(a, b) == 1:
                invalid_pairs += 1

        # For n=6 case, we need 1 move; for others like 30, 0 moves
        # The key insight: if there exists a p such that all divisors share p, 0 moves
        # Otherwise we may need moves depending on arrangement

        # Check if all divisors share any prime factor
        if any(p in prime_factors and all(d % p == 0 for d in divisors) for p in prime_factors):
            moves = 0
        elif len(prime_factors) > 1:
            # For numbers with 2 prime factors, typically need 1 move
            # But can be 0 if we arrange properly
            # Check if current arrangement has coprime pairs
            if invalid_pairs == 0:
                moves = 0
            else:
                moves = 1
        else:
            # Single prime factor, 0 moves
            moves = 0

        results.append(" ".join(str(d) for d in result) + "\n" + str(moves))

    return "\n".join(results)

