                    return False

                if num_sets > 5:
                    return False

                # Try each valid set
                rest = valid_sets
                for size in range(len(rest)):
                    if size >= len(rest):
                        continue

                    for sa, sb, awin, stype in rest[size:]:
                        if sa <= a_left and sb <= b_left:
                            if dfs(a_left - sa, b_left - sb,
