                return [s for a, b, w, t in sets]

            if a_left < 0 or b_left < 0 or a_wins > num_a or b_wins > num_b:
                return None

            for sa, sb, awin, stype in valid_sets:
                if sa <= a_left and sb <= b_left:
                    new_a = a_wins + (1 if awin else 0)
                    new_b = b_wins + (1 if not awin else 0)
                    new_sets = sets + [(sa, sb, awin, stype)]

                    res = dfs(a_left - sa, b_left - sb, new_a, new_b, new_sets)
                    if res is not None:
                        return res

            return None

        return reconstruct_solution(total_a, total_b, num_a, num_b)

    idx = 1
    for _ in range(m):
        if idx >= len(lines):
            break

        parts = lines[idx].strip().split()
