def brute_force(n, edges, adj, result=None, used=None):
    if result is None:
        result = []
        used = [False] * len(edges)

    # Find unused edges
    remaining = [i for i in range(len(edges)) if not used[i]]

    if not remaining:
        return " ".join(" ".join(str(x) for x in path) + "\n" for path in result)

    first = remaining[0]
    u1, v1 = edges[first]

    # Try pairing with each adjacent unused edge
    paths_from_first = adj[u1] + adj[v1]

    for idx, i in enumerate(paths_from_first):
        if not (i[0] in remaining or i[1] == first and not any(e[0] == i[1] and e[1] == first for e in edges)):
            u2, v2 = edges[i]
            if i == first or used[i]:
                continue

            # If we can form a path of length 2
            if i != first:
                # Check if these edges can form a valid path
                # First edge: u1-v1, Second edge: v1-u2 or u2-v1
                second_candidate = None
                if second_candidate is None:
                    if adj[v1] and not used[second_candidate[0]]:
                        u3, v3 = edges[second_candidate[0]]
                        if v3 == u1 or u3 == u1:
