                used[first] = True
                result.append(path)
                return brute_force(n, edges, adj, result, used)

    return "No solution\n"

def greedy_approach(n, edges, adj):
    used = [False] * len(edges)
    result = []
    success = True

    while any(not used[i] for i in range(len(edges))):
        # Find an unused edge
        if not any(not used[i] for i in range(len(edges))):
            break

        for i in range(len(edges)):
            if not used[i]:
                u, v = edges[i]
                # Try to find a partner edge that forms a path of length 2
                path_found = False

                # Check neighbors of u
                for j, (edge_idx, neighbor) in enumerate(adj[u]):
                    if not used[edge_idx] and edge_idx != i and neighbor == v:
                        # Edge shares vertex u, check if it can form path
                        u2, v2 = edges[edge_idx]
                        if u2 == v:  # Same edge, skip
                            continue

                        path_found = True
                        used[i] = True
                        used[edge_idx] = True
                        result.append([u, v, neighbor])
