Looking at this problem, I need to model it as a state-space search where each state represents which items John currently has. Since n ≤ 50, we have 2^50 possible subsets, but the exchange constraint limits reachability.

Key insights:
1. John can either **take** new items from market (without giving up anything) or **exchange** items (give up some, take some)
2. Each operation changes the total value by at most d
3. BFS from empty state to find maximum value with minimum days

```python
import collections
from itertools import combinations

def solution(input_str):
    lines = input_str.strip().split('\n')
    try:
        n, d = map(int, lines[0].split())
        c = list(map(int, lines[1].split()))
    except:
        return "0 0"

    total = sum(c)
    if n == 0:
        return "0 0"

    # BFS: state is frozenset of items John owns
    start = frozenset()
    visited = {start}
    queue = collections.deque([(start, 0)])

    max_value = 0
    best_days = 0

    while queue:
        state, days = queue.popleft()
        current_value = sum(c[i] for i in state)

        if current_value > max_value:
            max_value = current_value
            best_days = days

        if current_value >= total:
            break

        market = [i for i in range(n) if i not in state]

        # Option 1: Take new items (no exchange, just add)
        for size in range(len(market) + 1):
            for y in combinations(market, size):
                y_set = set(y)
                gain = sum(c[i] for i in y_set)
                if gain <= d:
                    new_state = frozenset(state | y_set)
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, days + 1))

        # Option 2: Exchange (give up items, take new items)
        for size1 in range(1, len(state) + 1):
            for x in combinations(state, size1):
                x_set = set(x)
                for size2 in range(len(market) + 1):
                    for y in combinations(market, size2):
                        y_set = set(y)
                        if not y_set:
                            continue

                        new_state = frozenset((state - x_set) | y_set)

                        if new_state in visited:
                            continue

                        old_val = sum(c[i] for i in state)
                        new_val = sum(c[i] for i in new_state)

                        if new_val - old_val <= d:
                            visited.add(new_state)
                            queue.append((new_state, days + 1))

    return f"{max_value} {best_days}"
